//! Port of the shared parts of `foundation/discovery/icon-set-writer.mjs`
//! that checks and the icon commands both read: the generated module's
//! statements and declaration text, the theme map name, an icon's other
//! names, and the entry wiring note. The authoring steps live with the
//! command (`commands::experimental::icon::authoring`).

use crate::json::Value;

pub const THEME_MAP_NAME: &str = "themeIcons";
const ADAPTER_LOCAL: &str = "adaptIcon";

pub const GENERATED_HEADER: [&str; 4] = [
    "// Generated by `astryx experimental icon` (new-set, add, map): one export per icon of this set.",
    "// Edit with those commands; a statement added by hand is kept.",
    "// themeIcons has one entry per built-in icon definition in map (the names Core renders), not one per icon;",
    "// the import lines above it give it local names for the re-exported icons.",
];

fn re_replace(re: &str, flags: &str, s: &str, f: &dyn Fn(&regress::Match, &str) -> String) -> String {
    let r = regress::Regex::with_flags(re, flags).unwrap();
    let mut out = String::new();
    let mut last = 0;
    for m in r.find_iter(s) {
        out.push_str(&s[last..m.start()]);
        out.push_str(&f(&m, s));
        last = m.end();
    }
    out.push_str(&s[last..]);
    out
}

/// `normalizedStatement(statement)`.
pub fn normalized_statement(statement: &str) -> String {
    let a = re_replace(r"\s+", "gu", statement, &|_, _| " ".into());
    let b = re_replace(r#""((?:[^"'\\]|\\.)*)""#, "gu", &a, &|m, t| format!("'{}'", &t[m.group(1).unwrap()]));
    let c = re_replace(r"([{(]) ", "gu", &b, &|m, t| t[m.group(1).unwrap()].to_string());
    let d = re_replace(r"[,;]? ?([})])", "gu", &c, &|m, t| t[m.group(1).unwrap()].to_string());
    let e = crate::commands::gap_report::api::js_trim(&d).to_string();
    re_replace(r" ?;$", "u", &e, &|_, _| String::new())
}

fn terminated(statement: &str) -> String {
    let re = regress::Regex::new(r"^(?:export (?:default )?)?(?:declare )?(?:abstract )?(?:async )?(?:function\b|class\b|interface\b|enum\b|namespace\b|module\b)").unwrap();
    if re.find(statement).is_some() {
        statement.to_string()
    } else {
        format!("{statement};")
    }
}

/// `generatedStatements(text, label)`: Err is the refusal message.
fn generated_statements(text: &str, label: &str) -> Result<Vec<String>, String> {
    use oxc::allocator::Allocator;
    use oxc::ast::ast::{TSInterfaceBody, TSTypeLiteral};
    use oxc::ast_visit::{walk, Visit};
    use oxc::parser::Parser;
    use oxc::span::{GetSpan, SourceType};
    let alloc = Allocator::default();
    let ret = Parser::new(&alloc, text, SourceType::tsx().with_module(true)).parse();
    if let Some(e) = ret.diagnostics.first() {
        return Err(format!(
            "The generated icons module {label} does not parse ({}). Fix or delete it, then run the command again.",
            e.message
        ));
    }
    struct Ends(Vec<u32>);
    impl<'a> Visit<'a> for Ends {
        fn visit_ts_type_literal(&mut self, t: &TSTypeLiteral<'a>) {
            for m in &t.members {
                self.0.push(m.span().end);
            }
            walk::walk_ts_type_literal(self, t);
        }
        fn visit_ts_interface_body(&mut self, b: &TSInterfaceBody<'a>) {
            for m in &b.body {
                self.0.push(m.span().end);
            }
            walk::walk_ts_interface_body(self, b);
        }
    }
    let bytes = text.as_bytes();
    let mut out = vec![];
    for node in &ret.program.body {
        let span = node.span();
        let (start, end) = (span.start as usize, span.end as usize);
        let mut v = Ends(vec![]);
        v.visit_statement(node);
        let mut seps: Vec<usize> = v
            .0
            .into_iter()
            .map(|e| e as usize)
            .filter(|&e| !(e < bytes.len() && (bytes[e] == b';' || bytes[e] == b',')))
            .filter(|&e| !(e > 0 && (bytes[e - 1] == b';' || bytes[e - 1] == b',')))
            .collect();
        seps.sort_by(|a, b| b.cmp(a));
        let mut statement = text[start..end].to_string();
        for e in seps {
            let at = e - start;
            if at <= statement.len() {
                statement.insert(at, ';');
            }
        }
        out.push(normalized_statement(&statement));
    }
    Ok(out)
}

/// `readGeneratedStatements(text, label)`.
pub fn read_generated_statements(text: &str, label: &str) -> Result<Vec<String>, String> {
    generated_statements(text, label)
}

/// `generatedTypesMatch(actual, expected, label)`.
pub fn generated_types_match(actual: &str, expected: &str, label: &str) -> bool {
    let Ok(have) = generated_statements(actual, label) else { return false };
    let Ok(want) = generated_statements(expected, label) else { return false };
    have == want
}

/// `generatedTypesText(statements)`.
pub fn generated_types_text(statements: &[String]) -> String {
    let mut lines: Vec<String> = vec![];
    let mut react: Vec<&str> = vec![];
    let add = |react: &mut Vec<&'static str>, n: &'static str| {
        if !react.contains(&n) {
            react.push(n);
        }
    };
    let reexport = regress::Regex::new(r"^export (?:\*|\{[^}]*\}) from ").unwrap();
    let adapted_re = regress::Regex::new(&format!(r"^export const (\w+) = {ADAPTER_LOCAL}\(")).unwrap();
    let theme_re = regress::Regex::new(r"^export const (\w+) = \{(.*)\}$").unwrap();
    let key_re = regress::Regex::new(r"(\w+): createElement\(").unwrap();
    for given in statements {
        let statement = normalized_statement(given);
        if statement.starts_with("import ") {
            continue;
        }
        if reexport.find(&statement).is_some() {
            lines.push(terminated(&statement));
            continue;
        }
        if let Some(m) = adapted_re.find(&statement) {
            add(&mut react, "ComponentType");
            add(&mut react, "SVGProps");
            lines.push(format!("export declare const {}: ComponentType<SVGProps<SVGSVGElement>>;", &statement[m.group(1).unwrap()]));
            continue;
        }
        if let Some(m) = theme_re.find(&statement) {
            let name = &statement[m.group(1).unwrap()];
            if name == THEME_MAP_NAME || statement.contains("createElement(") {
                add(&mut react, "ReactElement");
                let body = &statement[m.group(2).unwrap()];
                let keys: Vec<String> = key_re.find_iter(body).map(|k| format!("readonly {}: ReactElement", &body[k.group(1).unwrap()])).collect();
                lines.push(format!("export declare const {name}: {{{}}};", keys.join("; ")));
            }
        }
    }
    let mut out: Vec<String> = GENERATED_HEADER.iter().map(|s| s.to_string()).collect();
    if !react.is_empty() {
        let mut r = react.clone();
        r.sort_by(|a, b| crate::discovery::jsort::cmp_utf16(a, b));
        out.push(format!("import type {{{}}} from 'react';", r.join(", ")));
    }
    out.extend(lines);
    out.push(String::new());
    out.join("\n")
}

/// `otherNamesOf(icon)`: each word that is not a part of the id.
pub fn other_names_of(id: &str, words: &[String]) -> Vec<String> {
    let parts: Vec<&str> = id.split('-').collect();
    words.iter().filter(|w| !parts.contains(&w.as_str())).cloned().collect()
}

/// `entryWiringNote(packageDir, pkg, generated, {module, name})`.
pub fn entry_wiring_note(package_dir: &str, pkg: &Value, generated: &str, module: Option<&str>, name: Option<&str>) -> Option<String> {
    crate::commands::experimental::icon::authoring::entry_wiring_note_with(package_dir, pkg, generated, module, name)
}
